<?php require __DIR__.'/../includes/bootstrap.php';require_auth();if((user()['role']??'')!=='admin'){http_response_code(403);exit('Administrator access required.');}if(!collector_marketplace_ready())redirect('upgrade-collector-marketplace.php');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('UPDATE collector_profiles SET status=?,is_featured=? WHERE id=?')->execute([$_POST['status']??'pending',isset($_POST['is_featured'])?1:0,(int)$_POST['id']]);flash('success','Collector updated.');redirect('admin/collectors.php');}$rows=db()->query('SELECT cp.*,u.display_name,u.email,(SELECT COUNT(*) FROM collector_items i WHERE i.collector_id=cp.id) item_count FROM collector_profiles cp JOIN users u ON u.id=cp.user_id ORDER BY cp.created_at DESC')->fetchAll();app_header('Collector Admin');?><section class="dashboard-hero"><p class="eyebrow">ADMINISTRATION</p><h1>Collector Marketplace</h1><p>Approve collector profiles and feature trusted community sellers.</p></section><section class="admin-table-wrap"><table><thead><tr><th>Collector</th><th>User</th><th>Items</th><th>Status</th><th>Controls</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="../collectors/view.php?slug=<?=urlencode($r['slug'])?>"><?=e($r['shop_name'])?></a></td><td><?=e($r['display_name'])?><br><small><?=e($r['email'])?></small></td><td><?=(int)$r['item_count']?></td><td><?=e($r['status'])?></td><td><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['pending','approved','suspended'] as $st):?><option value="<?=$st?>" <?=$r['status']===$st?'selected':''?>><?=ucfirst($st)?></option><?php endforeach?></select><label><input type="checkbox" name="is_featured" <?=$r['is_featured']?'checked':''?>> Featured</label><button>Save</button></form></td></tr><?php endforeach?></tbody></table></section><?php app_footer();
